// TestGenerate2393ReviewSnapshots is appended to a complete copy of review_authors_test.go.
func TestGenerate2393ReviewSnapshots(t *testing.T) {
	makeComment := func(id, author int64, name, body, reply, resolve string) forge.MRComment {
		c := inline(id, author, name, body, raT0)
		c.ReplyID, c.ResolveID = reply, resolve
		return c
	}
	member := makeComment(239301, memberID, "m2-collaborator", "M2-ELIGIBLE-COLLABORATOR-BODY", "m2-reply-collaborator", "m2-resolve-collaborator")
	bot := makeComment(239302, coderabbit, "coderabbitai[bot]", "M2-ELIGIBLE-BOT-BODY", "m2-reply-bot", "m2-resolve-bot")
	outsider := makeComment(239303, outsiderID, "m2-outsider", "M2-WITHHELD-OUTSIDER-BODY", "m2-withheld-reply-outsider", "m2-withheld-resolve-outsider")
	unknown := makeComment(239304, flakyID, "m2-unknown", "M2-WITHHELD-UNKNOWN-BODY", "m2-withheld-reply-unknown", "m2-withheld-resolve-unknown")
	generate := func(comments ...forge.MRComment) *workersvc.ReviewCommentsSnapshot {
		h := newHarness()
		// flakyID is unscripted: lookupFake returns an immediate error, never a timer.
		p := h.params(comments...)
		p.Trusted = []settings.TrustedBot{{BaseURL: "https://github.com", ForgeUserID: coderabbit}}
		return h.snapshot(t, p).Snapshot
	}
	mixed := generate(member, bot, outsider, unknown)
	allWithheld := generate(outsider, unknown)
	if mixed.Version != 2 || len(mixed.Comments) != 2 || mixed.WithheldNotEligible != 1 || mixed.WithheldUnknown != 1 {
		t.Fatalf("unexpected mixed snapshot: %+v", mixed)
	}
	if allWithheld.Version != 2 || len(allWithheld.Comments) != 0 || allWithheld.WithheldNotEligible != 1 || allWithheld.WithheldUnknown != 1 {
		t.Fatalf("unexpected all-withheld snapshot: %+v", allWithheld)
	}
	h := newHarness()
	empty, err := h.assessor().Begin(context.Background(), h.params())
	if err != nil || empty != nil {
		t.Fatalf("zero-input Begin = %v, %v; want nil, nil", empty, err)
	}
	snapshots := map[string]*workersvc.ReviewCommentsSnapshot{"mixed": mixed, "all_withheld": allWithheld}
	raw, err := json.MarshalIndent(snapshots, "", "  ")
	if err != nil { t.Fatal(err) }
	for _, c := range []forge.MRComment{outsider, unknown} {
		for _, canary := range []string{c.Body, c.ReplyID, c.ResolveID} {
			if strings.Contains(string(raw), canary) { t.Fatalf("snapshot leaked %q", canary) }
		}
	}
	if err := os.WriteFile("../../../.uzi/scratch/2393-generated-snapshots.json", append(raw, '\n'), 0600); err != nil { t.Fatal(err) }
	t.Log("generated mixed and all-withheld via Begin -> Snapshot; withheld canaries excluded; zero-input Begin nil")
}
